/**
 * Seed all countries from the EXTRA list that don't already exist.
 * Skips countries already present in the DB (uk, usa, canada, australia,
 * germany, netherlands) — those are handled by seed-higher-study.ts.
 */
export async function seedExtraCountries(db: PrismaClient): Promise<void> {
  console.log("  Seeding extended countries (extra destinations)...");
  let created = 0;
  let updated = 0;
  for (const c of COUNTRIES) {
    const result = await db.higherStudyCountry.upsert({
      where: { slug: c.slug },
      update: {
        // Re-fill any null fields on update, but keep existing non-null values.
        officialName: c.officialName,
        region: c.region,
        overview: c.overview,
        educationSystem: c.educationSystem,
        studyLevels: c.studyLevels,
        popularSubjects: c.popularSubjects,
        tuitionFeeRange: c.tuitionFeeRange,
        livingCostRange: c.livingCostRange,
        majorStudentCities: c.majorStudentCities,
        admissionRequirements: c.admissionRequirements,
        englishRequirements: c.englishRequirements,
        availableIntakes: c.availableIntakes,
        applicationDeadlines: c.applicationDeadlines,
        scholarshipsAvailable: c.scholarshipsAvailable,
        researchOpportunities: c.researchOpportunities,
        studentVisaOverview: c.studentVisaOverview,
        financialEvidence: c.financialEvidence,
        workRights: c.workRights,
        postStudyOpportunities: c.postStudyOpportunities,
        accommodation: c.accommodation,
        healthcare: c.healthcare,
        transport: c.transport,
        studentSafety: c.studentSafety,
        culturalInfo: c.culturalInfo,
        applicationProcess: c.applicationProcess,
        requiredDocuments: c.requiredDocuments,
        officialSourceUrl: c.officialSourceUrl,
        flagEmoji: c.flagEmoji,
        status: "published",
        lastVerifiedAt: new Date(),
      },
      create: {
        slug: c.slug,
        name: c.name,
        officialName: c.officialName,
        region: c.region,
        overview: c.overview,
        educationSystem: c.educationSystem,
        studyLevels: c.studyLevels,
        popularSubjects: c.popularSubjects,
        tuitionFeeRange: c.tuitionFeeRange,
        livingCostRange: c.livingCostRange,
        majorStudentCities: c.majorStudentCities,
        admissionRequirements: c.admissionRequirements,
        englishRequirements: c.englishRequirements,
        availableIntakes: c.availableIntakes,
        applicationDeadlines: c.applicationDeadlines,
        scholarshipsAvailable: c.scholarshipsAvailable,
        researchOpportunities: c.researchOpportunities,
        studentVisaOverview: c.studentVisaOverview,
        financialEvidence: c.financialEvidence,
        workRights: c.workRights,
        postStudyOpportunities: c.postStudyOpportunities,
        accommodation: c.accommodation,
        healthcare: c.healthcare,
        transport: c.transport,
        studentSafety: c.studentSafety,
        culturalInfo: c.culturalInfo,
        applicationProcess: c.applicationProcess,
        requiredDocuments: c.requiredDocuments,
        officialSourceUrl: c.officialSourceUrl,
        flagEmoji: c.flagEmoji,
        status: "published",
        lastVerifiedAt: new Date(),
      },
    });
    if (result.createdAt.getTime() > Date.now() - 60000) created++;
    else updated++;
  }
  console.log(`    ✓ ${COUNTRIES.length} extra countries processed (${created} created, ${updated} updated)`);
}

// Allow standalone execution
if (require.main === module) {
  const db = new PrismaClient();
  seedExtraCountries(db)
    .then(() => db.$disconnect())
    .catch((e) => {
      console.error(e);
      process.exit(1);
    });
}
